from pathlib import Path
from datetime import date
import csv, re, sys

ROOT = Path('/app/logs')
OUT = Path('/app/summary.csv')
REF = date(2025, 8, 12)
windows = {
    'today': (REF, REF),
    'last_7_days': (date(2025, 8, 6), REF),
    'last_30_days': (date(2025, 7, 14), REF),
    'month_to_date': (date(2025, 8, 1), REF),
    'total': (None, None),
}
severities = ('ERROR', 'WARNING', 'INFO')
counts = {period: {sev: 0 for sev in severities} for period in windows}

file_re = re.compile(r'^(\d{4})-(\d{2})-(\d{2})_.*\.log$')
sev_re = re.compile(r'\[(ERROR|WARNING|INFO)\]')

log_files = sorted(ROOT.glob('*.log'))
for path in log_files:
    m = file_re.match(path.name)
    if not m:
        continue
    d = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    text = path.read_text(errors='replace').splitlines()
    file_counts = {sev: 0 for sev in severities}
    for line in text:
        sm = sev_re.search(line)
        if sm:
            file_counts[sm.group(1)] += 1
    for sev in severities:
        counts['total'][sev] += file_counts[sev]
    for period, (start, end) in windows.items():
        if period == 'total':
            continue
        if start <= d <= end:
            for sev in severities:
                counts[period][sev] += file_counts[sev]

rows = [('period', 'severity', 'count')]
for period in ('today', 'last_7_days', 'last_30_days', 'month_to_date', 'total'):
    for sev in severities:
        rows.append((period, sev, str(counts[period][sev])))

with OUT.open('w', newline='') as f:
    writer = csv.writer(f)
    writer.writerows(rows)

# independent validation: reread and recompute from scratch
expected = {period: {sev: 0 for sev in severities} for period in windows}
for path in log_files:
    m = file_re.match(path.name)
    if not m:
        continue
    d = date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    lines = path.read_text(errors='replace').splitlines()
    for line in lines:
        sm = sev_re.search(line)
        if not sm:
            continue
        sev = sm.group(1)
        expected['total'][sev] += 1
        for period, (start, end) in windows.items():
            if period == 'total':
                continue
            if start <= d <= end:
                expected[period][sev] += 1

# compare file contents row-for-row
content = OUT.read_text().splitlines()
assert len(content) == 16, f'expected 16 lines, got {len(content)}'
assert content[0] == 'period,severity,count', content[0]
expected_lines = ['period,severity,count'] + [f'{p},{s},{expected[p][s]}' for p in ('today','last_7_days','last_30_days','month_to_date','total') for s in severities]
assert content == expected_lines, '\n'.join(['EXPECTED:'] + expected_lines + ['GOT:'] + content)

print('WROTE', OUT)
for line in expected_lines:
    print(line)
